  public static func add(TREND_M_S_PER_DAY: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: TREND_M_S_PER_DAY, def: .nan, at: VT.TREND_M_S_PER_DAY) }
  public static func add(OLD_LEVEL_SET_MS: Int64, _ fbb: inout FlatBufferBuilder) { fbb.add(element: OLD_LEVEL_SET_MS, def: 0, at: VT.OLD_LEVEL_SET_MS) }
  public static func add(NEW_LEVEL_SET_MS: Int64, _ fbb: inout FlatBufferBuilder) { fbb.add(element: NEW_LEVEL_SET_MS, def: 0, at: VT.NEW_LEVEL_SET_MS) }
