  public static func add(PLANE_GLR_STATISTIC: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: PLANE_GLR_STATISTIC, def: .nan, at: VT.PLANE_GLR_STATISTIC) }
  public static func add(PLANE_STEP_M_S: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: PLANE_STEP_M_S, def: .nan, at: VT.PLANE_STEP_M_S) }
  public static func add(RATE_CHANGE_M_S_PER_DAY: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: RATE_CHANGE_M_S_PER_DAY, def: .nan, at: VT.RATE_CHANGE_M_S_PER_DAY) }
  public static func add(RATE_CHANGE_SD: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: RATE_CHANGE_SD, def: .nan, at: VT.RATE_CHANGE_SD) }
  public static func add(TREND_BEFORE_M_S_PER_DAY: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: TREND_BEFORE_M_S_PER_DAY, def: .nan, at: VT.TREND_BEFORE_M_S_PER_DAY) }
  public static func addVectorOf(COMPONENTS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: COMPONENTS, at: VT.COMPONENTS) }
  public static func add(KEPT: mdeDetector, _ fbb: inout FlatBufferBuilder) { fbb.add(element: KEPT.rawValue, def: 0, at: VT.KEPT) }
  public static func endMDEEvidence(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createMDEEvidence(
    _ fbb: inout FlatBufferBuilder,
    DETECTOR: mdeDetector = .unspecified,
    TIME_MS: Int64 = 0,
    PAIR_INDEX: Int32 = -1,
    STEP_IN_TRACK_M_S: Double = .nan,
    STEP_PLANE_M_S: Double = .nan,
    THRESHOLD_IN_TRACK_M_S: Double = .nan,
    THRESHOLD_PLANE_M_S: Double = .nan,
    CROSSING_AT_EDGE: Bool = false,
    SPAN_START_MS: Int64 = 0,
    SPAN_STOP_MS: Int64 = 0,
    GLR_STATISTIC: Double = .nan,
    STEP_M_S: Double = .nan,
    STEP_SD_M_S: Double = .nan,
    SIGMA_M_S: Double = .nan,
    TREND_M_S_PER_DAY: Double = .nan,
    OLD_LEVEL_SET_MS: Int64 = 0,
    NEW_LEVEL_SET_MS: Int64 = 0,
    TIME_BASIS: mdeTimeBasis = .unspecified,
    PLANE_GLR_STATISTIC: Double = .nan,
    PLANE_STEP_M_S: Double = .nan,
    RATE_CHANGE_M_S_PER_DAY: Double = .nan,
    RATE_CHANGE_SD: Double = .nan,
    TREND_BEFORE_M_S_PER_DAY: Double = .nan,
    COMPONENTSVectorOffset COMPONENTS: Offset = Offset(),
    KEPT: mdeDetector = .unspecified
  ) -> Offset {
    let __start = MDEEvidence.startMDEEvidence(&fbb)
    MDEEvidence.add(DETECTOR: DETECTOR, &fbb)
    MDEEvidence.add(TIME_MS: TIME_MS, &fbb)
    MDEEvidence.add(PAIR_INDEX: PAIR_INDEX, &fbb)
    MDEEvidence.add(STEP_IN_TRACK_M_S: STEP_IN_TRACK_M_S, &fbb)
    MDEEvidence.add(STEP_PLANE_M_S: STEP_PLANE_M_S, &fbb)
    MDEEvidence.add(THRESHOLD_IN_TRACK_M_S: THRESHOLD_IN_TRACK_M_S, &fbb)
    MDEEvidence.add(THRESHOLD_PLANE_M_S: THRESHOLD_PLANE_M_S, &fbb)
    MDEEvidence.add(CROSSING_AT_EDGE: CROSSING_AT_EDGE, &fbb)
    MDEEvidence.add(SPAN_START_MS: SPAN_START_MS, &fbb)
    MDEEvidence.add(SPAN_STOP_MS: SPAN_STOP_MS, &fbb)
    MDEEvidence.add(GLR_STATISTIC: GLR_STATISTIC, &fbb)
    MDEEvidence.add(STEP_M_S: STEP_M_S, &fbb)
    MDEEvidence.add(STEP_SD_M_S: STEP_SD_M_S, &fbb)
    MDEEvidence.add(SIGMA_M_S: SIGMA_M_S, &fbb)
    MDEEvidence.add(TREND_M_S_PER_DAY: TREND_M_S_PER_DAY, &fbb)
    MDEEvidence.add(OLD_LEVEL_SET_MS: OLD_LEVEL_SET_MS, &fbb)
    MDEEvidence.add(NEW_LEVEL_SET_MS: NEW_LEVEL_SET_MS, &fbb)
    MDEEvidence.add(TIME_BASIS: TIME_BASIS, &fbb)
    MDEEvidence.add(PLANE_GLR_STATISTIC: PLANE_GLR_STATISTIC, &fbb)
    MDEEvidence.add(PLANE_STEP_M_S: PLANE_STEP_M_S, &fbb)
    MDEEvidence.add(RATE_CHANGE_M_S_PER_DAY: RATE_CHANGE_M_S_PER_DAY, &fbb)
    MDEEvidence.add(RATE_CHANGE_SD: RATE_CHANGE_SD, &fbb)
    MDEEvidence.add(TREND_BEFORE_M_S_PER_DAY: TREND_BEFORE_M_S_PER_DAY, &fbb)
    MDEEvidence.addVectorOf(COMPONENTS: COMPONENTS, &fbb)
    MDEEvidence.add(KEPT: KEPT, &fbb)
    return MDEEvidence.endMDEEvidence(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.DETECTOR, fieldName: "DETECTOR", required: false, type: mdeDetector.self)
    try _v.visit(field: VT.TIME_MS, fieldName: "TIME_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.PAIR_INDEX, fieldName: "PAIR_INDEX", required: false, type: Int32.self)
    try _v.visit(field: VT.STEP_IN_TRACK_M_S, fieldName: "STEP_IN_TRACK_M_S", required: false, type: Double.self)
    try _v.visit(field: VT.STEP_PLANE_M_S, fieldName: "STEP_PLANE_M_S", required: false, type: Double.self)
    try _v.visit(field: VT.THRESHOLD_IN_TRACK_M_S, fieldName: "THRESHOLD_IN_TRACK_M_S", required: false, type: Double.self)
    try _v.visit(field: VT.THRESHOLD_PLANE_M_S, fieldName: "THRESHOLD_PLANE_M_S", required: false, type: Double.self)
    try _v.visit(field: VT.CROSSING_AT_EDGE, fieldName: "CROSSING_AT_EDGE", required: false, type: Bool.self)
    try _v.visit(field: VT.SPAN_START_MS, fieldName: "SPAN_START_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.SPAN_STOP_MS, fieldName: "SPAN_STOP_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.GLR_STATISTIC, fieldName: "GLR_STATISTIC", required: false, type: Double.self)
    try _v.visit(field: VT.STEP_M_S, fieldName: "STEP_M_S", required: false, type: Double.self)
    try _v.visit(field: VT.STEP_SD_M_S, fieldName: "STEP_SD_M_S", required: false, type: Double.self)
    try _v.visit(field: VT.SIGMA_M_S, fieldName: "SIGMA_M_S", required: false, type: Double.self)
    try _v.visit(field: VT.TREND_M_S_PER_DAY, fieldName: "TREND_M_S_PER_DAY", required: false, type: Double.self)
    try _v.visit(field: VT.OLD_LEVEL_SET_MS, fieldName: "OLD_LEVEL_SET_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.NEW_LEVEL_SET_MS, fieldName: "NEW_LEVEL_SET_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.TIME_BASIS, fieldName: "TIME_BASIS", required: false, type: mdeTimeBasis.self)
    try _v.visit(field: VT.PLANE_GLR_STATISTIC, fieldName: "PLANE_GLR_STATISTIC", required: false, type: Double.self)
    try _v.visit(field: VT.PLANE_STEP_M_S, fieldName: "PLANE_STEP_M_S", required: false, type: Double.self)
    try _v.visit(field: VT.RATE_CHANGE_M_S_PER_DAY, fieldName: "RATE_CHANGE_M_S_PER_DAY", required: false, type: Double.self)
    try _v.visit(field: VT.RATE_CHANGE_SD, fieldName: "RATE_CHANGE_SD", required: false, type: Double.self)
    try _v.visit(field: VT.TREND_BEFORE_M_S_PER_DAY, fieldName: "TREND_BEFORE_M_S_PER_DAY", required: false, type: Double.self)
    try _v.visit(field: VT.COMPONENTS, fieldName: "COMPONENTS", required: false, type: ForwardOffset<Vector<ForwardOffset<MDEEvidence>, MDEEvidence>>.self)
    try _v.visit(field: VT.KEPT, fieldName: "KEPT", required: false, type: mdeDetector.self)
    _v.finish()
  }
}

///  One event a detector raised.
public struct MDEEvent: FlatBufferVerifiableTable, FlatbuffersVectorInitializable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$MDE" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: MDEEvent.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let DETECTOR: VOffset = 4
    static let TIME_MS: VOffset = 6
    static let CHARACTERIZATION: VOffset = 8
    static let IN_TRACK_M_S: VOffset = 10
    static let CROSS_TRACK_M_S: VOffset = 12
    static let IN_TRACK_FIRED: VOffset = 14
    static let CROSS_TRACK_FIRED: VOffset = 16
    static let RAW_IN_TRACK_M_S: VOffset = 18
    static let RAW_CROSS_TRACK_M_S: VOffset = 20
    static let DELTA_SMA_KM: VOffset = 22
    static let SEPARATION_KM: VOffset = 24
    static let TIME_FROM_CROSSING: VOffset = 26
    static let BLOCK_BEFORE: VOffset = 28
    static let BLOCK_AFTER: VOffset = 30
    static let EVIDENCE: VOffset = 32
    static let ACCEL_CHANGE_M_S2: VOffset = 34
    static let MNV_ID: VOffset = 36
  }

  public var DETECTOR: mdeDetector { let o = _accessor.offset(VT.DETECTOR); return o == 0 ? .unspecified : mdeDetector(rawValue: _accessor.readBuffer(of: UInt8.self, at: o)) ?? .unspecified }
  ///  Event time, Unix ms.
  public var TIME_MS: Int64 { let o = _accessor.offset(VT.TIME_MS); return o == 0 ? 0 : _accessor.readBuffer(of: Int64.self, at: o) }
  public var CHARACTERIZATION: maneuverCharacterization { let o = _accessor.offset(VT.CHARACTERIZATION); return o == 0 ? .unknown : maneuverCharacterization(rawValue: _accessor.readBuffer(of: Int8.self, at: o)) ?? .unknown }
  ///  In-track delta-v, m/s; 0 unless its test fired.
  public var IN_TRACK_M_S: Double { let o = _accessor.offset(VT.IN_TRACK_M_S); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Cross-track delta-v, m/s; 0 unless its test fired.
  public var CROSS_TRACK_M_S: Double { let o = _accessor.offset(VT.CROSS_TRACK_M_S); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  public var IN_TRACK_FIRED: Bool { let o = _accessor.offset(VT.IN_TRACK_FIRED); return o == 0 ? false : _accessor.readBuffer(of: Bool.self, at: o) }
  public var CROSS_TRACK_FIRED: Bool { let o = _accessor.offset(VT.CROSS_TRACK_FIRED); return o == 0 ? false : _accessor.readBuffer(of: Bool.self, at: o) }
  ///  In-track and cross-track estimates before the firing rule, m/s.
  public var RAW_IN_TRACK_M_S: Double { let o = _accessor.offset(VT.RAW_IN_TRACK_M_S); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  public var RAW_CROSS_TRACK_M_S: Double { let o = _accessor.offset(VT.RAW_CROSS_TRACK_M_S); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Semi-major axis change, km.
  public var DELTA_SMA_KM: Double { let o = _accessor.offset(VT.DELTA_SMA_KM); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Separation at the crossing, km.
  public var SEPARATION_KM: Double { let o = _accessor.offset(VT.SEPARATION_KM); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  True when TIME_MS is a crossing time (else a gap middle).
  public var TIME_FROM_CROSSING: Bool { let o = _accessor.offset(VT.TIME_FROM_CROSSING); return o == 0 ? false : _accessor.readBuffer(of: Bool.self, at: o) }
  ///  Indices of the history blocks (element sets or versions) before and
  ///  after the event.
  public var BLOCK_BEFORE: UInt32 { let o = _accessor.offset(VT.BLOCK_BEFORE); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  public var BLOCK_AFTER: UInt32 { let o = _accessor.offset(VT.BLOCK_AFTER); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  public var EVIDENCE: MDEEvidence? { let o = _accessor.offset(VT.EVIDENCE); return o == 0 ? nil : MDEEvidence(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  ///  D3: change of along-track acceleration, m/s**2; NaN = not computed.
  public var ACCEL_CHANGE_M_S2: Double { let o = _accessor.offset(VT.ACCEL_CHANGE_M_S2); return o == 0 ? .nan : _accessor.readBuffer(of: Double.self, at: o) }
  ///  ID of the $MNV record emitted for the event; empty when not emitted.
  public var MNV_ID: String? { let o = _accessor.offset(VT.MNV_ID); return o == 0 ? nil : _accessor.string(at: o) }
  public var MNV_IDSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.MNV_ID) }
  public static func startMDEEvent(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 17) }
  public static func add(DETECTOR: mdeDetector, _ fbb: inout FlatBufferBuilder) { fbb.add(element: DETECTOR.rawValue, def: 0, at: VT.DETECTOR) }
  public static func add(TIME_MS: Int64, _ fbb: inout FlatBufferBuilder) { fbb.add(element: TIME_MS, def: 0, at: VT.TIME_MS) }
  public static func add(CHARACTERIZATION: maneuverCharacterization, _ fbb: inout FlatBufferBuilder) { fbb.add(element: CHARACTERIZATION.rawValue, def: 9, at: VT.CHARACTERIZATION) }
  public static func add(IN_TRACK_M_S: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: IN_TRACK_M_S, def: 0.0, at: VT.IN_TRACK_M_S) }
  public static func add(CROSS_TRACK_M_S: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: CROSS_TRACK_M_S, def: 0.0, at: VT.CROSS_TRACK_M_S) }
  public static func add(IN_TRACK_FIRED: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: IN_TRACK_FIRED, def: false,
   at: VT.IN_TRACK_FIRED) }
  public static func add(CROSS_TRACK_FIRED: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: CROSS_TRACK_FIRED, def: false,
   at: VT.CROSS_TRACK_FIRED) }
  public static func add(RAW_IN_TRACK_M_S: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: RAW_IN_TRACK_M_S, def: 0.0, at: VT.RAW_IN_TRACK_M_S) }
  public static func add(RAW_CROSS_TRACK_M_S: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: RAW_CROSS_TRACK_M_S, def: 0.0, at: VT.RAW_CROSS_TRACK_M_S) }
  public static func add(DELTA_SMA_KM: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: DELTA_SMA_KM, def: 0.0, at: VT.DELTA_SMA_KM) }
  public static func add(SEPARATION_KM: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: SEPARATION_KM, def: 0.0, at: VT.SEPARATION_KM) }
  public static func add(TIME_FROM_CROSSING: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: TIME_FROM_CROSSING, def: false,
   at: VT.TIME_FROM_CROSSING) }
  public static func add(BLOCK_BEFORE: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: BLOCK_BEFORE, def: 0, at: VT.BLOCK_BEFORE) }
  public static func add(BLOCK_AFTER: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: BLOCK_AFTER, def: 0, at: VT.BLOCK_AFTER) }
  public static func add(EVIDENCE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: EVIDENCE, at: VT.EVIDENCE) }
  public static func add(ACCEL_CHANGE_M_S2: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: ACCEL_CHANGE_M_S2, def: .nan, at: VT.ACCEL_CHANGE_M_S2) }
  public static func add(MNV_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: MNV_ID, at: VT.MNV_ID) }
  public static func endMDEEvent(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createMDEEvent(
    _ fbb: inout FlatBufferBuilder,
    DETECTOR: mdeDetector = .unspecified,
    TIME_MS: Int64 = 0,
    CHARACTERIZATION: maneuverCharacterization = .unknown,
    IN_TRACK_M_S: Double = 0.0,
    CROSS_TRACK_M_S: Double = 0.0,
    IN_TRACK_FIRED: Bool = false,
    CROSS_TRACK_FIRED: Bool = false,
    RAW_IN_TRACK_M_S: Double = 0.0,
    RAW_CROSS_TRACK_M_S: Double = 0.0,
    DELTA_SMA_KM: Double = 0.0,
    SEPARATION_KM: Double = 0.0,
    TIME_FROM_CROSSING: Bool = false,
    BLOCK_BEFORE: UInt32 = 0,
    BLOCK_AFTER: UInt32 = 0,
    EVIDENCEOffset EVIDENCE: Offset = Offset(),
    ACCEL_CHANGE_M_S2: Double = .nan,
    MNV_IDOffset MNV_ID: Offset = Offset()
  ) -> Offset {
    let __start = MDEEvent.startMDEEvent(&fbb)
    MDEEvent.add(DETECTOR: DETECTOR, &fbb)
    MDEEvent.add(TIME_MS: TIME_MS, &fbb)
    MDEEvent.add(CHARACTERIZATION: CHARACTERIZATION, &fbb)
    MDEEvent.add(IN_TRACK_M_S: IN_TRACK_M_S, &fbb)
    MDEEvent.add(CROSS_TRACK_M_S: CROSS_TRACK_M_S, &fbb)
    MDEEvent.add(IN_TRACK_FIRED: IN_TRACK_FIRED, &fbb)
    MDEEvent.add(CROSS_TRACK_FIRED: CROSS_TRACK_FIRED, &fbb)
    MDEEvent.add(RAW_IN_TRACK_M_S: RAW_IN_TRACK_M_S, &fbb)
    MDEEvent.add(RAW_CROSS_TRACK_M_S: RAW_CROSS_TRACK_M_S, &fbb)
    MDEEvent.add(DELTA_SMA_KM: DELTA_SMA_KM, &fbb)
    MDEEvent.add(SEPARATION_KM: SEPARATION_KM, &fbb)
    MDEEvent.add(TIME_FROM_CROSSING: TIME_FROM_CROSSING, &fbb)
    MDEEvent.add(BLOCK_BEFORE: BLOCK_BEFORE, &fbb)
    MDEEvent.add(BLOCK_AFTER: BLOCK_AFTER, &fbb)
    MDEEvent.add(EVIDENCE: EVIDENCE, &fbb)
    MDEEvent.add(ACCEL_CHANGE_M_S2: ACCEL_CHANGE_M_S2, &fbb)
    MDEEvent.add(MNV_ID: MNV_ID, &fbb)
    return MDEEvent.endMDEEvent(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.DETECTOR, fieldName: "DETECTOR", required: false, type: mdeDetector.self)
    try _v.visit(field: VT.TIME_MS, fieldName: "TIME_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.CHARACTERIZATION, fieldName: "CHARACTERIZATION", required: false, type: maneuverCharacterization.self)
    try _v.visit(field: VT.IN_TRACK_M_S, fieldName: "IN_TRACK_M_S", required: false, type: Double.self)
    try _v.visit(field: VT.CROSS_TRACK_M_S, fieldName: "CROSS_TRACK_M_S", required: false, type: Double.self)
    try _v.visit(field: VT.IN_TRACK_FIRED, fieldName: "IN_TRACK_FIRED", required: false, type: Bool.self)
    try _v.visit(field: VT.CROSS_TRACK_FIRED, fieldName: "CROSS_TRACK_FIRED", required: false, type: Bool.self)
    try _v.visit(field: VT.RAW_IN_TRACK_M_S, fieldName: "RAW_IN_TRACK_M_S", required: false, type: Double.self)
    try _v.visit(field: VT.RAW_CROSS_TRACK_M_S, fieldName: "RAW_CROSS_TRACK_M_S", required: false, type: Double.self)
    try _v.visit(field: VT.DELTA_SMA_KM, fieldName: "DELTA_SMA_KM", required: false, type: Double.self)
    try _v.visit(field: VT.SEPARATION_KM, fieldName: "SEPARATION_KM", required: false, type: Double.self)
    try _v.visit(field: VT.TIME_FROM_CROSSING, fieldName: "TIME_FROM_CROSSING", required: false, type: Bool.self)
    try _v.visit(field: VT.BLOCK_BEFORE, fieldName: "BLOCK_BEFORE", required: false, type: UInt32.self)
    try _v.visit(field: VT.BLOCK_AFTER, fieldName: "BLOCK_AFTER", required: false, type: UInt32.self)
    try _v.visit(field: VT.EVIDENCE, fieldName: "EVIDENCE", required: false, type: ForwardOffset<MDEEvidence>.self)
    try _v.visit(field: VT.ACCEL_CHANGE_M_S2, fieldName: "ACCEL_CHANGE_M_S2", required: false, type: Double.self)
    try _v.visit(field: VT.MNV_ID, fieldName: "MNV_ID", required: false, type: ForwardOffset<String>.self)
    _v.finish()
  }
}

///  An element set dropped as a republication of another.
public struct MDEDuplicateEpoch: FlatBufferVerifiableTable, FlatbuffersVectorInitializable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
