    _ fbb: inout FlatBufferBuilder,
    OPTIONSOffset OPTIONS: Offset = Offset(),
    SUMMARYOffset SUMMARY: Offset = Offset(),
    MATCHESVectorOffset MATCHES: Offset = Offset(),
    MISSEDVectorOffset MISSED: Offset = Offset(),
    UNMATCHEDVectorOffset UNMATCHED: Offset = Offset()
  ) -> Offset {
    let __start = MDEScoreReport.startMDEScoreReport(&fbb)
    MDEScoreReport.add(OPTIONS: OPTIONS, &fbb)
    MDEScoreReport.add(SUMMARY: SUMMARY, &fbb)
    MDEScoreReport.addVectorOf(MATCHES: MATCHES, &fbb)
    MDEScoreReport.addVectorOf(MISSED: MISSED, &fbb)
    MDEScoreReport.addVectorOf(UNMATCHED: UNMATCHED, &fbb)
    return MDEScoreReport.endMDEScoreReport(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.OPTIONS, fieldName: "OPTIONS", required: false, type: ForwardOffset<MDEScoreOptions>.self)
    try _v.visit(field: VT.SUMMARY, fieldName: "SUMMARY", required: false, type: ForwardOffset<MDEScoreSummary>.self)
    try _v.visit(field: VT.MATCHES, fieldName: "MATCHES", required: false, type: ForwardOffset<Vector<ForwardOffset<MDETruthMatch>, MDETruthMatch>>.self)
    try _v.visit(field: VT.MISSED, fieldName: "MISSED", required: false, type: ForwardOffset<Vector<ForwardOffset<MDETruthMatch>, MDETruthMatch>>.self)
    try _v.visit(field: VT.UNMATCHED, fieldName: "UNMATCHED", required: false, type: ForwardOffset<Vector<ForwardOffset<MDEUnmatchedEvent>, MDEUnmatchedEvent>>.self)
    _v.finish()
